PRAGMA foreign_keys=ON;
CREATE TABLE Customer(customer_id TEXT PRIMARY KEY,signup_date TEXT NOT NULL,region TEXT NOT NULL,acquisition_channel TEXT NOT NULL,customer_segment TEXT NOT NULL,seasonality_type TEXT NOT NULL);
CREATE TABLE Subscription(subscription_id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES Customer(customer_id),product_cohort TEXT NOT NULL,plan_name TEXT NOT NULL,monthly_price REAL NOT NULL CHECK(monthly_price>=0),start_date TEXT NOT NULL,status TEXT NOT NULL,billing_cycle TEXT NOT NULL);
CREATE TABLE UsageSnapshot(snapshot_id TEXT PRIMARY KEY,subscription_id TEXT NOT NULL REFERENCES Subscription(subscription_id),customer_id TEXT NOT NULL REFERENCES Customer(customer_id),snapshot_date TEXT NOT NULL,usage_units REAL NOT NULL CHECK(usage_units>=0),active_days INTEGER NOT NULL);
CREATE TABLE BillingEvent(billing_event_id TEXT PRIMARY KEY,subscription_id TEXT NOT NULL REFERENCES Subscription(subscription_id),customer_id TEXT NOT NULL REFERENCES Customer(customer_id),billing_date TEXT NOT NULL,amount_due REAL NOT NULL,overdue_amount REAL NOT NULL,payment_status TEXT NOT NULL);
CREATE TABLE SupportCase(support_case_id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES Customer(customer_id),subscription_id TEXT NOT NULL REFERENCES Subscription(subscription_id),opened_date TEXT NOT NULL,case_type TEXT NOT NULL,priority TEXT NOT NULL,case_status TEXT NOT NULL);
CREATE TABLE Offer(offer_id TEXT PRIMARY KEY,offer_name TEXT NOT NULL,discount_rate REAL NOT NULL,duration_months INTEGER NOT NULL,max_cost REAL NOT NULL,active INTEGER NOT NULL);
CREATE TABLE EligibilityRule(eligibility_rule_id TEXT PRIMARY KEY,rule_name TEXT NOT NULL,min_churn_probability REAL NOT NULL,min_margin REAL NOT NULL,max_offer_cost REAL NOT NULL,active INTEGER NOT NULL);
CREATE TABLE CampaignContact(campaign_contact_id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES Customer(customer_id),group_name TEXT NOT NULL,offer_id TEXT REFERENCES Offer(offer_id),contact_date TEXT NOT NULL);
CREATE TABLE ChurnOutcome(customer_id TEXT PRIMARY KEY REFERENCES Customer(customer_id),churn_label INTEGER NOT NULL,prediction_date TEXT NOT NULL,horizon_months INTEGER NOT NULL);
CREATE TABLE RetentionOutcome(customer_id TEXT PRIMARY KEY REFERENCES Customer(customer_id),retained_6m INTEGER NOT NULL,retention_revenue REAL NOT NULL,offer_cost REAL NOT NULL,net_value REAL NOT NULL);
